import type { Metadata } from 'next';
import { notFound } from 'next/navigation';

import { BackButton } from '@/components/BackButton';
import { getAllPosts, getCommentsByPostId, getPostById } from '@/lib/blog-api';

type BlogPostPageProps = {
  params: Promise<{ id: string }>;
};

export const revalidate = 300;
export const dynamicParams = true;

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts = await getAllPosts({ next: { revalidate } });

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }));
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params;
  const post = await getPostById(id, { next: { revalidate } });

  if (!post) {
    return {
      title: 'Post Not Found',
      description: 'The requested blog post could not be found.',
    };
  }

  const excerpt = post.body.slice(0, 160);

  return {
    title: post.title,
    description: excerpt,
    openGraph: {
      title: post.title,
      description: excerpt,
    },
  };
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params;
  const post = await getPostById(id, { next: { revalidate } });

  if (!post) {
    notFound();
  }

  const comments = await getCommentsByPostId(id, { next: { revalidate } });

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}

