  id: string,
  init?: RequestInit
): Promise<Post | null> {
  const response = await fetch(`${JSON_PLACEHOLDER_API}/posts/${id}`, init);

  if (!response.ok) {
    if (response.status === 404) {
      return null;
    }

    throw new Error(`Request failed (${response.status}) for post ${id}`);
  }

  const data = (await response.json()) as Partial<Post>;

  if (typeof data.id !== 'number') {
    return null;
  }

  return data as Post;
}

