import { NextResponse } from 'next/server';

interface PostRecord {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
  updatedAt?: string;
}

interface DeleteMessage {
  message: string;
}

interface ApiError {
  error: string;
}

interface UpdatePostBody {
  title?: unknown;
  content?: unknown;
}

type PostRouteContext = {
  params: Promise<{ id: string }>;
};

function parseId(id: string): number | null {
  const parsed = Number.parseInt(id, 10);
  return Number.isNaN(parsed) ? null : parsed;
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}

export async function GET(
  _request: Request,
  { params }: PostRouteContext
): Promise<NextResponse<PostRecord | ApiError>> {
  const { id } = await params;
  const parsedId = parseId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  const post: PostRecord = {
    id: parsedId,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post);
}

export async function PUT(
  request: Request,
  { params }: PostRouteContext
): Promise<NextResponse<PostRecord | ApiError>> {
  const { id } = await params;
  const parsedId = parseId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  let body: UpdatePostBody;

  try {
    body = (await request.json()) as UpdatePostBody;
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const updatedPost: PostRecord = {
    id: parsedId,
    title: isNonEmptyString(body.title) ? body.title : `Post ${id}`,
    content:
      isNonEmptyString(body.content) ?
        body.content
      : `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return NextResponse.json(updatedPost);
}

export async function DELETE(
  _request: Request,
  { params }: PostRouteContext
): Promise<NextResponse<DeleteMessage | ApiError>> {
  const { id } = await params;
  const parsedId = parseId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  return NextResponse.json({ message: `Post ${id} deleted successfully` });
}

